CREATE OR REPLACE FUNCTION public._write_read_audit(p_event_name text, p_client_uuid uuid, p_metadata jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid := gen_random_uuid(); c public.audit_event_contract%ROWTYPE;
  v_actor uuid; v_role text; v_reason text; v_code text; v_n int;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN PERFORM public._record_audit_failure(p_event_name,'NO_VERIFIED_USER',NULL,'P0011'); RETURN NULL; END IF;
  v_role := public.get_app_role_for_user(v_actor);
  IF v_role <> 'admin' THEN PERFORM public._record_audit_failure(p_event_name,'READ_AUDIT_NOT_ADMIN',NULL,'P0016'); RETURN NULL; END IF;

  SELECT * INTO c FROM public.audit_event_contract WHERE event_name=p_event_name;
  IF NOT FOUND THEN PERFORM public._record_audit_failure(p_event_name,'UNKNOWN_EVENT',NULL,'P0001'); RETURN NULL; END IF;

  v_reason := public.audit_validate_event(p_event_name,'user','VIEW','audit_log',p_client_uuid,NULL,p_metadata);
  IF v_reason IS NOT NULL THEN
    PERFORM public._record_audit_failure(p_event_name,v_reason,ARRAY(SELECT jsonb_object_keys(coalesce(p_metadata,'{}'::jsonb))),'P0002'); RETURN NULL;
  END IF;

  IF p_client_uuid IS NOT NULL THEN
    SELECT count(*) INTO v_n FROM public.clients WHERE id=p_client_uuid;
    IF v_n<>1 THEN PERFORM public._record_audit_failure(p_event_name,'CLIENT_NOT_FOUND',NULL,'P0014'); RETURN NULL; END IF;
    SELECT client_id INTO v_code FROM public.clients WHERE id=p_client_uuid;
  END IF;

  INSERT INTO public.audit_log (
    id,initiated_by_type,actor_user_id,actor_service,actor_app_role,target_user_id,
    client_uuid,client_code_snapshot,resource_type,resource_id,
    event_name,event_category,action,description,risk_tier,sensitivity_tier,metadata
  ) VALUES (
    v_id,'user',v_actor,NULL,v_role,NULL,
    p_client_uuid,v_code,'audit_log',NULL,
    p_event_name,'audit','VIEW',NULL,c.risk_tier,c.sensitivity,p_metadata
  );
  RETURN v_id;
EXCEPTION WHEN OTHERS THEN
  PERFORM public._record_audit_failure(p_event_name,'DB_ERROR',NULL,SQLSTATE);
  RAISE WARNING 'read-audit insert failed for % (%):', p_event_name, SQLSTATE; RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_field_format_ok(p_field text, p_value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  t text := jsonb_typeof(p_value);
  s text := CASE WHEN jsonb_typeof(p_value)='string' THEN (p_value #>> '{}') ELSE p_value::text END;
  d date;
  ts timestamptz;
BEGIN
  IF t = 'null' THEN RETURN true; END IF;
  CASE p_field
    WHEN 'assigned_role_code'  THEN RETURN t='string' AND s = ANY (ARRAY['ADMIN','MANAGER','EXECUTIVE','STAFF','VIEWER','INTERN','DEVELOPER_TEST','CLIENT']);
    WHEN 'old_role_code'       THEN RETURN t='string' AND s = ANY (ARRAY['ADMIN','MANAGER','EXECUTIVE','STAFF','VIEWER','INTERN','DEVELOPER_TEST','CLIENT']);
    WHEN 'new_role_code'       THEN RETURN t='string' AND s = ANY (ARRAY['ADMIN','MANAGER','EXECUTIVE','STAFF','VIEWER','INTERN','DEVELOPER_TEST','CLIENT']);
    WHEN 'login_method_code'   THEN RETURN t='string' AND s = ANY (ARRAY['PASSWORD','OTP','MAGIC_LINK','PIN','SSO']);
    WHEN 'change_type_code'    THEN RETURN t='string' AND s = ANY (ARRAY['CREATED','UPDATED','DELETED','ENABLED','DISABLED','GRANTED','REVOKED']);
    WHEN 'logout_type_code'    THEN RETURN t='string' AND s = ANY (ARRAY['USER_INITIATED','TIMEOUT','FORCED','SYSTEM']);
    WHEN 'request_channel_code'THEN RETURN t='string' AND s = ANY (ARRAY['EMAIL','SMS','WHATSAPP','PORTAL']);
    WHEN 'reset_channel_code'  THEN RETURN t='string' AND s = ANY (ARRAY['EMAIL','SMS','WHATSAPP','PORTAL']);
    WHEN 'invite_method_code'  THEN RETURN t='string' AND s = ANY (ARRAY['EMAIL','MANUAL','SSO']);
    WHEN 'export_type_code'    THEN RETURN t='string' AND s = ANY (ARRAY['AUDIT_LOG','CLIENT_LIST','DOCUMENT_SET','COMPLIANCE_REPORT']);
    WHEN 'export_format_code'  THEN RETURN t='string' AND s = ANY (ARRAY['CSV','XLSX','PDF','JSON']);
    WHEN 'scope_code'          THEN RETURN t='string' AND s = ANY (ARRAY['SINGLE_CLIENT','ALL_CLIENTS','DATE_RANGE','FILTERED']);
    WHEN 'download_channel_code' THEN RETURN t='string' AND s = ANY (ARRAY['PORTAL','WHATSAPP','API']);
    WHEN 'requested_operation_code' THEN RETURN t='string' AND s = ANY (ARRAY['VIEW','EDIT','DOWNLOAD','EXPORT','DELETE']);
    WHEN 'detection_method_code' THEN RETURN t='string' AND s = ANY (ARRAY['RLS','APP_CHECK','RPC_GUARD','MANUAL_REVIEW']);
    WHEN 'permission_type_code'THEN RETURN t='string' AND s = ANY (ARRAY['CLIENT_ACCESS','SENSITIVE_VIEW','FINANCIAL_VIEW','DOC_DOWNLOAD']);
    WHEN 'access_method_code'  THEN RETURN t='string' AND s = ANY (ARRAY['RPC','BACKEND']);
    WHEN 'filter_risk_tier'    THEN RETURN t='string' AND s = ANY (ARRAY['LOW','MEDIUM','HIGH','CRITICAL']);
    WHEN 'change_reason_code'  THEN RETURN t='string' AND s ~ '^[A-Z][A-Z0-9_]{1,39}$';
    WHEN 'denial_reason_code'  THEN RETURN t='string' AND s ~ '^[A-Z][A-Z0-9_]{1,39}$';
    WHEN 'deactivation_reason_code' THEN RETURN t='string' AND s ~ '^[A-Z][A-Z0-9_]{1,39}$';
    WHEN 'reactivation_reason_code' THEN RETURN t='string' AND s ~ '^[A-Z][A-Z0-9_]{1,39}$';
    WHEN 'revocation_reason_code'   THEN RETURN t='string' AND s ~ '^[A-Z][A-Z0-9_]{1,39}$';
    WHEN 'failure_reason_code' THEN RETURN t='string' AND s ~ '^[A-Z][A-Z0-9_]{1,39}$';
    WHEN 'old_value_code'      THEN RETURN t='string' AND s ~ '^[A-Z][A-Z0-9_]{1,39}$';
    WHEN 'new_value_code'      THEN RETURN t='string' AND s ~ '^[A-Z][A-Z0-9_]{1,39}$';
    WHEN 'setting_name_code'   THEN RETURN t='string' AND s ~ '^[A-Z][A-Z0-9_]{1,39}$';
    WHEN 'triggering_event_name' THEN RETURN t='string' AND s ~ '^[a-z][a-z._]{1,60}$';
    WHEN 'compliance_type_code_filter' THEN RETURN t='string' AND s ~ '^[A-Z][A-Z0-9_]{1,39}$';
    WHEN 'attempt_count'             THEN RETURN t='number' AND s ~ '^[0-9]+$' AND s::numeric <= 1000;
    WHEN 'record_count'              THEN RETURN t='number' AND s ~ '^[0-9]+$' AND s::numeric <= 10000000;
    WHEN 'document_count'            THEN RETURN t='number' AND s ~ '^[0-9]+$' AND s::numeric <= 1000000;
    WHEN 'returned_row_count'        THEN RETURN t='number' AND s ~ '^[0-9]+$' AND s::numeric <= 10000000;
    WHEN 'total_match_count'         THEN RETURN t='number' AND s ~ '^[0-9]+$' AND s::numeric <= 100000000;
    WHEN 'row_count_exported'        THEN RETURN t='number' AND s ~ '^[0-9]+$' AND s::numeric <= 100000000;
    WHEN 'session_duration_seconds'  THEN RETURN t='number' AND s ~ '^[0-9]+$' AND s::numeric <= 31536000;
    WHEN 'time_since_request_seconds'THEN RETURN t='number' AND s ~ '^[0-9]+$' AND s::numeric <= 31536000;
    WHEN 'date_range_days'           THEN RETURN t='number' AND s ~ '^[0-9]+$' AND s::numeric <= 366;
    WHEN 'requested_page_number'     THEN RETURN t='number' AND s ~ '^[0-9]+$' AND s::numeric BETWEEN 1 AND 100000;
    WHEN 'requested_page_size'       THEN RETURN t='number' AND s ~ '^[0-9]+$' AND s::numeric BETWEEN 1 AND 200;
    WHEN 'filter_applied' THEN RETURN t='boolean';
    WHEN 'page_empty'     THEN RETURN t='boolean';
    WHEN 'read_request_audit_id' THEN RETURN t='string' AND public.audit_is_uuid(s);
    WHEN 'completion_status_code' THEN RETURN t='string' AND s = ANY (ARRAY['SUCCESS','PARTIAL','EMPTY']);
    WHEN 'login_subject_hmac' THEN RETURN t='string' AND s ~ '^[0-9a-f]{64}$';
    WHEN 'wa_actor_hmac'      THEN RETURN t='string' AND s ~ '^[0-9a-f]{64}$';
    WHEN 'table_name'  THEN RETURN t='string' AND s ~ '^[a-z_][a-z0-9_]{0,62}$';
    WHEN 'policy_name' THEN RETURN t='string' AND s ~ '^[A-Za-z0-9_ ]{1,80}$';
    WHEN 'migration_reference' THEN RETURN t='string' AND s ~ '^[0-9]{14}_[a-z0-9_]{1,80}$';
    WHEN 'date_range_start' THEN BEGIN d := s::date; RETURN true; EXCEPTION WHEN others THEN RETURN false; END;
    WHEN 'date_range_end'   THEN BEGIN d := s::date; RETURN true; EXCEPTION WHEN others THEN RETURN false; END;
    WHEN 'filter_date_start' THEN BEGIN ts := s::timestamptz; RETURN true; EXCEPTION WHEN others THEN RETURN false; END;
    WHEN 'filter_date_end'   THEN BEGIN ts := s::timestamptz; RETURN true; EXCEPTION WHEN others THEN RETURN false; END;
    WHEN 'filing_period_range' THEN RETURN t='string' AND s ~ '^([A-Z][a-z]{2}-[0-9]{2}|[0-9]{4}-[0-9]{2}|Q[1-4]-[0-9]{4})(\s*to\s*([A-Z][a-z]{2}-[0-9]{2}|[0-9]{4}-[0-9]{2}|Q[1-4]-[0-9]{4}))?$';
    WHEN 'user_agent_family' THEN RETURN t='string' AND char_length(s) BETWEEN 1 AND 60;
    WHEN 'portal_version'    THEN RETURN t='string' AND s ~ '^[0-9A-Za-z._-]{1,30}$';
    WHEN 'bot_version'       THEN RETURN t='string' AND s ~ '^[0-9A-Za-z._-]{1,30}$';
    WHEN 'session_reference_id' THEN RETURN t='string' AND s ~ '^[0-9A-Za-z._-]{1,64}$';
    ELSE RETURN false;
  END CASE;
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_is_uuid(p_text text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE v uuid;
BEGIN
  IF p_text IS NULL THEN RETURN false; END IF;
  BEGIN v := p_text::uuid; RETURN true;
  EXCEPTION WHEN others THEN RETURN false; END;
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_validate_event(p_event_name text, p_initiated_by_type text, p_action text, p_resource_type text, p_client_uuid uuid, p_target_user_id uuid, p_metadata jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  c   public.audit_event_contract%ROWTYPE;
  k   text; v jsonb; rk text; sval text;
  c_max_bytes int := 4000;
BEGIN
  SELECT * INTO c FROM public.audit_event_contract WHERE event_name = p_event_name;
  IF NOT FOUND THEN RETURN 'UNKNOWN_EVENT'; END IF;
  IF NOT (p_initiated_by_type = ANY (c.permitted_actor_types)) THEN RETURN 'ACTOR_TYPE_NOT_PERMITTED'; END IF;
  IF array_length(c.permitted_actions,1) IS NULL THEN
    IF p_action IS NOT NULL THEN RETURN 'ACTION_NOT_PERMITTED'; END IF;
  ELSE
    IF p_action IS NULL OR NOT (p_action = ANY (c.permitted_actions)) THEN RETURN 'ACTION_NOT_PERMITTED'; END IF;
  END IF;
  IF array_length(c.permitted_resource_types,1) IS NULL THEN
    IF p_resource_type IS NOT NULL THEN RETURN 'RESOURCE_TYPE_NOT_PERMITTED'; END IF;
  ELSE
    IF p_resource_type IS NULL OR NOT (p_resource_type = ANY (c.permitted_resource_types)) THEN RETURN 'RESOURCE_TYPE_NOT_PERMITTED'; END IF;
  END IF;
  IF c.client_requirement='required'   AND p_client_uuid IS NULL     THEN RETURN 'CLIENT_REQUIRED'; END IF;
  IF c.client_requirement='prohibited' AND p_client_uuid IS NOT NULL THEN RETURN 'CLIENT_PROHIBITED'; END IF;
  IF c.target_user_requirement='required'   AND p_target_user_id IS NULL     THEN RETURN 'TARGET_USER_REQUIRED'; END IF;
  IF c.target_user_requirement='prohibited' AND p_target_user_id IS NOT NULL THEN RETURN 'TARGET_USER_PROHIBITED'; END IF;
  IF p_metadata IS NULL OR jsonb_typeof(p_metadata) <> 'object' THEN RETURN 'METADATA_NOT_OBJECT'; END IF;
  IF octet_length(p_metadata::text) > c_max_bytes THEN RETURN 'METADATA_OVERSIZE'; END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(p_metadata))=0 AND NOT c.allow_empty_metadata THEN RETURN 'EMPTY_METADATA_NOT_ALLOWED'; END IF;
  FOREACH rk IN ARRAY c.required_keys LOOP
    IF NOT (p_metadata ? rk) THEN RETURN 'MISSING_REQUIRED_KEY:'||rk; END IF;
    v := p_metadata -> rk;
    IF jsonb_typeof(v) = 'null' THEN RETURN 'REQUIRED_NULL:'||rk; END IF;
    IF jsonb_typeof(v) = 'string' THEN
      sval := v #>> '{}';
      IF btrim(sval) = '' THEN RETURN 'REQUIRED_BLANK:'||rk; END IF;
    END IF;
    IF NOT public.audit_field_format_ok(rk, v) THEN RETURN 'BAD_FORMAT:'||rk; END IF;
  END LOOP;
  FOR k, v IN SELECT key, value FROM jsonb_each(p_metadata) LOOP
    IF NOT (k = ANY (c.required_keys) OR k = ANY (c.optional_keys)) THEN RETURN 'DISALLOWED_KEY:'||k; END IF;
    IF jsonb_typeof(v) IN ('object','array') THEN RETURN 'NESTED_NOT_ALLOWED:'||k; END IF;
    IF jsonb_typeof(v) = 'null' THEN RETURN 'OPTIONAL_NULL_NOT_ALLOWED:'||k; END IF;
    IF NOT public.audit_field_format_ok(k, v) THEN RETURN 'BAD_FORMAT:'||k; END IF;
    IF jsonb_typeof(v) = 'string' THEN
      sval := v #>> '{}';
      IF char_length(sval) > 500 THEN RETURN 'VALUE_OVERSIZE:'||k; END IF;
      IF public.audit_contains_secret(sval) THEN RETURN 'PROHIBITED_VALUE:'||k; END IF;
    END IF;
  END LOOP;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_write_event(p_event_name text, p_action text, p_resource_type text, p_resource_id text, p_client_id uuid, p_metadata jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor          uuid := auth.uid();
  v_actor_role     text;
  v_reject         text;
  v_client_code    text;
  v_risk           text;
  v_sens           text;
  v_event_category text;
  v_id             uuid := pg_catalog.gen_random_uuid();  -- id generated explicitly
BEGIN
  -- (1) Reject unauthenticated callers before any work.
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'NO_AUTH_CONTEXT';
  END IF;

  -- (2) Caller must be an ACTIVE team member (SECURITY DEFINER bypasses RLS, so
  --     re-assert). Exact live signature: public.is_active_user() RETURNS boolean.
  --     NULL-safe fail-closed: `NOT NULL` is NULL and a PL/pgSQL IF skips a NULL
  --     branch, so `IF NOT fn()` would deny FALSE but pass NULL. `IS DISTINCT FROM
  --     TRUE` denies both FALSE and NULL — access requires an explicit TRUE.
  IF public.is_active_user() IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'NOT_AUTHORISED_INACTIVE';
  END IF;

  -- (3) Caller must be Admin or Manager. Exact live signature:
  --     public.is_admin_or_manager() RETURNS boolean. NULL-safe fail-closed as above.
  IF public.is_admin_or_manager() IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'NOT_AUTHORISED';
  END IF;

  -- (4) Derive + retain the actor's application role via the confirmed helper.
  --     get_app_role_for_user returns 'denied' for a null/absent/inactive user; a
  --     caller that passed (2)+(3) must resolve to 'admin' or 'manager'. Anything
  --     else fails closed.
  v_actor_role := public.get_app_role_for_user(v_actor);
  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin','manager') THEN
    RAISE EXCEPTION 'NOT_AUTHORISED_ROLE: %', coalesce(v_actor_role,'<null>');
  END IF;

  -- Tiers MUST come from the contract, not the caller.
  SELECT c.risk_tier, c.sensitivity
    INTO v_risk, v_sens
  FROM public.audit_event_contract c
  WHERE c.event_name = p_event_name;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'UNKNOWN_AUDIT_EVENT: %', p_event_name;
  END IF;

  -- event_category is DERIVED (family prefix), never accepted from the caller.
  v_event_category := split_part(p_event_name, '.', 1);
  IF v_event_category IS NULL OR v_event_category = '' THEN
    RAISE EXCEPTION 'UNRESOLVED_EVENT_CATEGORY: %', p_event_name;
  END IF;

  -- When a client UUID is supplied, confirm it exists and snapshot its code.
  IF p_client_id IS NOT NULL THEN
    SELECT cl.client_id INTO v_client_code
    FROM public.clients cl WHERE cl.id = p_client_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'CLIENT_NOT_FOUND: %', p_client_id;
    END IF;
  END IF;

  -- Validate action/resource/metadata through the canonical validator (actor
  -- 'user'). audit_validate_event RETURNS a rejection code (NULL on success) — it
  -- does not raise — so we inspect the result and RAISE on any non-empty code.
  v_reject := public.audit_validate_event(
                p_event_name, 'user', p_action, p_resource_type,
                p_client_id, NULL, p_metadata);
  IF v_reject IS NOT NULL AND v_reject <> '' THEN
    RAISE EXCEPTION 'AUDIT_VALIDATION_FAILED: %', v_reject;
  END IF;

  -- Insert the audit row atomically within the caller's transaction, binding the
  -- EXACT live audit_log columns (0005). initiated_by_type='user' satisfies
  -- chk_actor_user (actor_user_id NOT NULL, actor_service NULL).
  INSERT INTO public.audit_log
    (id, initiated_by_type, actor_user_id, actor_service, actor_app_role, target_user_id,
     client_uuid, client_code_snapshot, resource_type, resource_id,
     event_name, event_category, action, description, risk_tier, sensitivity_tier, metadata)
  VALUES
    (v_id, 'user', v_actor, NULL, v_actor_role, NULL,
     p_client_id, v_client_code, p_resource_type, p_resource_id,
     p_event_name, v_event_category, p_action, NULL, v_risk, v_sens,
     coalesce(p_metadata, '{}'::jsonb));

  RETURN v_id;
END
$function$

CREATE OR REPLACE FUNCTION public.get_app_role()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE v_count int; v_admin boolean; v_portal text;
BEGIN
  IF auth.uid() IS NULL THEN RETURN 'anon'; END IF;
  SELECT count(*) INTO v_count FROM public.team t WHERE t.auth_user_id=auth.uid() AND t.is_active=true;
  IF v_count <> 1 THEN RETURN 'anon'; END IF;
  SELECT t.is_admin, t.portal_role::text INTO v_admin, v_portal
    FROM public.team t WHERE t.auth_user_id=auth.uid() AND t.is_active=true;
  IF v_admin THEN RETURN 'admin'; END IF;
  RETURN CASE v_portal
    WHEN 'Admin'     THEN 'admin'
    WHEN 'Manager'   THEN 'manager'
    WHEN 'Executive' THEN 'staff'
    WHEN 'Staff'     THEN 'staff'
    WHEN 'Viewer'    THEN 'viewer'
    ELSE 'denied'
  END;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_app_role_for_user(p_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE v_count int; v_admin boolean; v_portal text;
BEGIN
  IF p_user_id IS NULL THEN RETURN 'denied'; END IF;
  SELECT count(*) INTO v_count FROM public.team t WHERE t.auth_user_id=p_user_id AND t.is_active=true;
  IF v_count <> 1 THEN RETURN 'denied'; END IF;
  SELECT t.is_admin, t.portal_role::text INTO v_admin, v_portal
    FROM public.team t WHERE t.auth_user_id=p_user_id AND t.is_active=true;
  IF v_admin THEN RETURN 'admin'; END IF;
  RETURN CASE v_portal
    WHEN 'Admin'     THEN 'admin'
    WHEN 'Manager'   THEN 'manager'
    WHEN 'Executive' THEN 'staff'
    WHEN 'Staff'     THEN 'staff'
    WHEN 'Viewer'    THEN 'viewer'
    ELSE 'denied'
  END;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_sensitive_audit_logs(p_from timestamp with time zone, p_to timestamp with time zone, p_page_number integer, p_page_size integer, p_risk_tier text DEFAULT NULL::text, p_client_uuid uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_req_id uuid; v_offset bigint; v_result jsonb;
  v_total bigint; v_returned int;
  c_max_page int := 200; c_max_pageno int := 100000; c_max_range interval := interval '92 days';
  v_req_meta jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not authenticated' USING ERRCODE='42501'; END IF;
  IF public.get_app_role() <> 'admin' THEN RAISE EXCEPTION 'not authorised' USING ERRCODE='42501'; END IF;
  IF p_from IS NULL OR p_to IS NULL OR p_from > p_to THEN RAISE EXCEPTION 'invalid date range' USING ERRCODE='22023'; END IF;
  IF (p_to - p_from) > c_max_range THEN RAISE EXCEPTION 'date range exceeds 92 days' USING ERRCODE='22023'; END IF;
  IF p_page_number IS NULL OR p_page_number < 1 OR p_page_number > c_max_pageno THEN RAISE EXCEPTION 'page_number out of range (1..100000)' USING ERRCODE='22023'; END IF;
  IF p_page_size IS NULL OR p_page_size < 1 OR p_page_size > c_max_page THEN RAISE EXCEPTION 'page_size must be 1..200' USING ERRCODE='22023'; END IF;
  IF p_risk_tier IS NOT NULL AND p_risk_tier <> ALL (ARRAY['LOW','MEDIUM','HIGH','CRITICAL']) THEN RAISE EXCEPTION 'invalid risk_tier filter' USING ERRCODE='22023'; END IF;

  v_offset := (p_page_number::bigint - 1) * p_page_size::bigint;

  -- 1) read_requested (exact scope, truthful pre-execution facts; fail-closed)
  v_req_meta := jsonb_build_object(
    'requested_page_number', p_page_number,
    'requested_page_size',   p_page_size,
    'filter_applied',        (p_risk_tier IS NOT NULL OR p_client_uuid IS NOT NULL),
    'access_method_code',    'RPC',
    'filter_date_start',     to_char(p_from AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'filter_date_end',       to_char(p_to   AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
  ) || (CASE WHEN p_risk_tier IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('filter_risk_tier',p_risk_tier) END);

  v_req_id := public._write_read_audit('audit.log.read_requested', p_client_uuid, v_req_meta);
  IF v_req_id IS NULL THEN
    RAISE EXCEPTION 'audit logging failed; sensitive read refused (fail-closed)' USING ERRCODE='42501';
  END IF;

  -- 2) ONE statement: items + total + returned + total_pages from one snapshot
  WITH filtered AS MATERIALIZED (
    SELECT a.*
      FROM public.audit_log a
     WHERE a.id <> v_req_id
       AND a.occurred_at BETWEEN p_from AND p_to
       AND (p_risk_tier  IS NULL OR a.risk_tier  = p_risk_tier)
       AND (p_client_uuid IS NULL OR a.client_uuid = p_client_uuid)
  ),
  page_rows AS MATERIALIZED (
    SELECT * FROM filtered
     ORDER BY occurred_at DESC, id DESC
     LIMIT p_page_size OFFSET v_offset
  )
  SELECT
    jsonb_build_object(
      'items',          COALESCE((SELECT jsonb_agg(to_jsonb(pr) ORDER BY pr.occurred_at DESC, pr.id DESC) FROM page_rows pr), '[]'::jsonb),
      'total_count',    (SELECT count(*) FROM filtered),
      'returned_count', (SELECT count(*) FROM page_rows),
      'page_number',    p_page_number,
      'page_size',      p_page_size,
      'total_pages',    CASE WHEN (SELECT count(*) FROM filtered)=0 THEN 0
                             ELSE CEIL((SELECT count(*) FROM filtered)::numeric / p_page_size)::bigint END,
      'out_of_range',   (p_page_number > CASE WHEN (SELECT count(*) FROM filtered)=0 THEN 0
                             ELSE CEIL((SELECT count(*) FROM filtered)::numeric / p_page_size)::bigint END
                         AND (SELECT count(*) FROM filtered) > 0)
    ),
    (SELECT count(*) FROM filtered),
    (SELECT count(*) FROM page_rows)::int
  INTO v_result, v_total, v_returned;

  -- 3) read_completed: linked to the exact request event via the server-derived
  --    v_req_id (finding v8 #1). The request event is authoritative for read
  --    scope (date range, client, risk tier); the completion event records only
  --    outcome facts plus the immutable correlation id (finding v8 #2).
  --    read_request_audit_id is NEVER a caller input — it is v_req_id::text.
  IF public._write_read_audit('audit.log.read_completed', p_client_uuid,
       jsonb_build_object(
         'read_request_audit_id', v_req_id::text,
         'returned_row_count',    v_returned,
         'total_match_count',     v_total,
         'page_empty',            (v_returned = 0),
         'completion_status_code',CASE WHEN v_returned = 0 THEN 'EMPTY' ELSE 'SUCCESS' END,
         'requested_page_number', p_page_number,
         'requested_page_size',   p_page_size,
         'access_method_code',    'RPC'
       )
     ) IS NULL THEN
    RAISE EXCEPTION 'audit completion logging failed; sensitive read refused (fail-closed)' USING ERRCODE='42501';
  END IF;

  RETURN v_result;
END;
$function$
